from wordfreq import count_words
import pytest

def test_count_words_empty_string():
    assert count_words('') == {}

def test_count_words_single_word():
    assert count_words('hello') == {'hello': 1}

def test_count_words_multiple_words():
    assert count_words('hello world hello') == {'hello': 2, 'world': 1}

def test_count_words_punctuation():
    assert count_words('Hello, hello!') == {'hello': 2}

def test_count_words_case_sensitivity():
    assert count_words('Hello hello') == {'hello': 2}

